package frontend

type Item struct {
	ID   string
	Name string
}

type ItemsPage struct {
	Items     []Item
	NextCursor *string
}

func ItemsEndpoint(cursor string, limit int) string {
	return "/items?cursor=" + cursor + "&limit=" + string(rune(limit))
}

func RenderItems(page ItemsPage) string {
	result := ""
	for _, item := range page.Items {
		result += item.ID + ":" + item.Name + "\n"
	}
	return result
}

func NextPageCursor(page ItemsPage) *string {
	return page.NextCursor
}

